package cn.hydrogen.launcher;import android.app.*;import android.content.*;public final class DesktopReturnChecks{static int checks;static void check(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}public static void main(String[] args){Context c=new Context();ActivityManager am=new ActivityManager();c.manager=am;DesktopReturnReceiver r=new DesktopReturnReceiver();Intent back=new Intent(DesktopReturnReceiver.ACTION);MainActivity first=new MainActivity(823);DesktopReturnReceiver.attach(first);r.onReceive(c,new Intent("wrong"));check(am.count==0&&c.started==null,"ignore unrelated action");r.onReceive(c,back);check(am.moved==823&&am.count==1&&c.started==null,"return raises original task without creating a new Activity");check(first.page==1,"second desktop page retained");MainActivity next=new MainActivity(826);DesktopReturnReceiver.attach(next);DesktopReturnReceiver.detach(first);r.onReceive(c,back);check(am.moved==826&&c.started==null,"old Activity cleanup cannot clear new task owner");am.denied=true;r.onReceive(c,back);check(c.started!=null&&c.started.target==MainActivity.class&&c.started.action==null&&c.started.retains,"denied reorder falls back to explicit component without HOME category");am.denied=false;c.started=null;next.finishing=true;r.onReceive(c,back);check(c.started!=null&&am.count==2,"finishing desktop not reused");next.finishing=false;c.started=null;UnifiedInitService.ready=false;r.onReceive(c,back);check(c.started!=null&&am.count==2,"no stale admission bypass");UnifiedInitService.ready=true;c.started=null;DesktopReturnReceiver.detach(next);r.onReceive(c,back);check(c.started!=null&&am.count==2,"missing weak owner uses guarded Main entry");System.out.println("RESULT desktop-return checks="+checks+" PASS (production receiver; JVM Android stubs)");}}